local names, authors = {}, {}
for _, line in ipairs(OPEN_ICONIC) do
  for name in line:gmatch("%S+") do names[#names + 1] = name end
end
for _, line in ipairs(PHOSPHOR) do
  for name in line:gmatch("%S+") do names[#names + 1] = "ph:" .. name end
end
for _, block in ipairs(GAME_ICONS) do
  local who = block[1]
  for i = 2, #block do
    for name in block[i]:gmatch("%S+") do
      local full = "gi:" .. name
      names[#names + 1] = full
      authors[full] = who
    end
  end
end

lib.__SetGeneratedIcons(names, authors)
